const fs=require('fs'),p=require('path'),c=require('crypto'),b=process.argv[2];function read(n){return JSON.parse(fs.readFileSync(p.join(b,n),'utf8').replace(/^\uFEFF/,''))}for(let id of [1,2,3,4,5,12]){const a='A'+('0'+id).slice(-2),fn=a+'_raport.json',d=read(fn);console.log('\n',a,c.createHash('sha256').update(fs.readFileSync(p.join(b,fn))).digest('hex'),d.status||d.decision||d.report_status);console.log('METRICS',JSON.stringify(d.denominators||d.coverage||d.counts).slice(0,3300));for(const f of d.findings||[])console.log('FINDING',f.id||f.finding_id,f.severity||f.prioritate||f.gravitate,f.title||f.titlu,f.confidence||f.incredere,'keys',Object.keys(f).slice(0,8).join('|'));if(id<=5){console.log('CK',Object.keys(d.controls[0]),'PL',Object.keys(d.pipelines[0]));}if(id===12)console.log('RECORD',JSON.stringify(d.records[0]).slice(0,1900),'LIMIT',d.remaining_work);}
console.log('A12FINDINGS',JSON.stringify(read('A12_constatari_prima_trecere.json').findings.map(x=>[x.id||x.finding_id,x.title||x.titlu,x.status])).slice(0,2200));
